"""Verify reversible archives and fixed ownership, then remove only verified duplicates."""
import hashlib,json,subprocess,time,shlex
from pathlib import Path
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'evidence/round3'
def remote(script):
 return subprocess.check_output(['ssh','imech192',script],text=True)
while not (OUT/'ARCHIVE_COMPLETE.json').exists() or not (OUT/'distribution_plan.json').exists():time.sleep(30)
assert not any('pedcontact' in x for x in remote('squeue -u luttkule -h -o "%j"').splitlines())
# Metadata/indexes mirrored first; preserve case/identity JSON and manifest bytes.
for sub in ['evidence/round2/fit/','evidence/round3/fit/']:
 subprocess.run(['rsync','-a','--exclude=*.npz.pcx','imech192:'+str(ROOT/sub)+'/',str(ROOT/sub)+'/'],check=True)
plan=json.loads((OUT/'distribution_plan.json').read_text());names=[]
for bank in plan['old_fit_banks_to_local']:
 p=ROOT/bank/'LOSSLESS_ARCHIVE_INDEX.json';index=json.loads(p.read_text());assert len(index['members'])==18
 names.extend(bank+'/'+r['archive'] for r in index['members'])
filelist=OUT/'transfer_archives.txt';filelist.write_text('\n'.join(names)+'\n')
subprocess.run(['rsync','-a','--files-from='+str(filelist),'imech192:'+str(ROOT)+'/',str(ROOT)+'/'],check=True)
verified=[]
for bank in plan['old_fit_banks_to_local']:
 index=json.loads((ROOT/bank/'LOSSLESS_ARCHIVE_INDEX.json').read_text())
 for r in index['members']:
  p=ROOT/bank/r['archive'];assert hashlib.sha256(p.read_bytes()).hexdigest()==r['archive_sha256'],str(p);verified.append(str(p.relative_to(ROOT)))
# Check local Round3 step4 archives cover every original manifest digest.
root_index=json.loads((OUT/'step4/LOSSLESS_ARCHIVE_INDEX.json').read_text());local_sha={r['path']:r['original_sha256'] for r in root_index['members']}
assert len(local_sha)==2160
for p in (OUT/'step4').rglob('SHA256SUMS'):
 for line in p.read_text().splitlines():
  if len(line.split())==2:
   sha,name=line.split()
   if name.endswith('.npz'):assert local_sha[str((p.parent/name).relative_to(OUT/'step4'))]==sha
# Remote deletion script independently checks the exact transfer roster and archives.
remote_plan=OUT/'distribution_plan.json';subprocess.run(['rsync','-a',str(remote_plan),'imech192:'+str(remote_plan)],check=True)
script='''import json,hashlib
from pathlib import Path
root=Path('/home/luttkule/lanes/pedcontact');out=root/'evidence/round3';p=json.loads((out/'distribution_plan.json').read_text())
for bank in p['old_fit_banks_to_local']:
 index=json.loads((root/bank/'LOSSLESS_ARCHIVE_INDEX.json').read_text())
 for r in index['members']:
  f=root/bank/r['archive'];assert hashlib.sha256(f.read_bytes()).hexdigest()==r['archive_sha256'];f.unlink()
for indexpath in (out/'step4').rglob('LOSSLESS_ARCHIVE_INDEX.json'):
 index=json.loads(indexpath.read_text())
 for r in index['members']:
  f=indexpath.parent/r['archive'];assert hashlib.sha256(f.read_bytes()).hexdigest()==r['archive_sha256'];f.unlink()
print('Removed only verified transferred/step4 archive duplicates')
'''
print(remote('cd '+str(ROOT)+' && repo/.venv/bin/python -c '+shlex.quote(script)),flush=True)
subprocess.run(['rsync','-a',str(ROOT/'custody_round3.py'),'imech192:'+str(ROOT)+'/'],check=True)
print(remote('cd '+str(ROOT)+' && repo/.venv/bin/python custody_round3.py'),flush=True)
subprocess.run(['rsync','-a','imech192:'+str(OUT/'custody_remote.json'),str(OUT/'custody_remote.json')],check=True)
subprocess.run([str(ROOT/'repo/.venv/bin/python'),str(ROOT/'custody_round3.py')],check=True)
local=json.loads((OUT/'custody_local.json').read_text());rem=json.loads((OUT/'custody_remote.json').read_text());decl=json.loads((ROOT/'repo/docs/pedcontact_10101_round3_custody.json').read_text());owners={}
for rec in [local,rem]:
 for c in rec['collections']:
  for x in c['indexes']:
   for m in x['archives_here']:
    orig=m['path'].removesuffix('.pcx');owners.setdefault(orig,[]).append(rec['host'])
for c in decl['collections']:
 for bank in c['banks']:
  for m in bank['members']:
   if m['trajectory']:
    found=owners.get(m['path'],[]);assert len(found)==1,(m['path'],found);assert bank['trajectory_owner'] in found[0],(m['path'],found,bank['trajectory_owner'])
(OUT/'custody_final.json').write_text(json.dumps(dict(local=local,remote=rem,transferred_archives=len(verified),declared_ownership_verified=True,no_original_trajectory_lost=True,claim='Every declared original trajectory has one SHA-verified reversible archive on its declared host; decoder checked original ZIP bytes before raw removal.'),indent=2))
print('CUSTODY FINAL VERIFIED',len(owners),flush=True)

