fit_runtime_round3.py.content:
"""Report every completed candidate's measured integration cost and repair counters."""
import hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'evidence/round3'
sys.path.insert(0,str(ROOT/'repo'))
from scripts.validation.pedcontact_10101 import interval
fit=json.loads((OUT/'fit/fit_result.json').read_text());points=[]
digests={}
for manifest in (OUT/'fit/banks').glob('*/*/SHA256SUMS'):
 for line in manifest.read_text().splitlines():
  if len(line.split())==2:
   digest,name=line.split();digests[str((manifest.parent/name).relative_to(OUT))]=digest
for ranked in fit['ranking']:
 rows=[]
 for seed in fit['seeds']:
  for p in sorted((OUT/'fit/banks'/ranked['point']['id']/str(seed)).glob('case_*.json')):
   assert hashlib.sha256(p.read_bytes()).hexdigest()==digests[str(p.relative_to(OUT))]
   rows.append(json.loads(p.read_text()))
 assert len(rows)==54
 all_steps=[r for row in rows for r in row['step_runtime']]
 dense={}
 for width in sorted({row['variant'] for row in rows if row['case']=='V4'}):
  bank=[row for row in rows if row['case']=='V4' and row['variant']==width]
  timing=[1000*sum(s['step_time_s'] for s in row['step_runtime'])/sum(s['steps'] for s in row['step_runtime']) for row in bank]
  dense[width]=interval(timing)
 points.append({'id':ranked['point']['id'],'passed_items':ranked['passed_items'],'radius_m':ranked['point']['radius_m'],'runtime_ms_per_step':1000*sum(r['step_time_s'] for r in all_steps)/sum(r['steps'] for r in all_steps),'dense_V4_runtime_ms_per_step':dense,'step_runtime':all_steps})
receipt={'producer_sha':fit['source_sha'],'seeds':fit['seeds'],'claim':'Complete fitted-parameter integration cost including warm-up and congestion; different wall/radius/cap settings need not meet the default fixed-snapshot ratio. Original per-run counters retained.','points':points}
(OUT/'fit_runtime.json').write_text(json.dumps(receipt,indent=2));print('fit runtime points',len(points))

frozen_robot_collector_round3.py.content:
"""Verify all paired dev robot gate banks and retain row-level regression evidence."""
import argparse,collections,hashlib,json,math,re
from pathlib import Path
ARMS=['orca','scenario_adaptive_hybrid_orca_v2_bottleneck_yield_v4','scenario_adaptive_hybrid_orca_v2_collision_guard_v4','hybrid_rule_v4_fast_progress_static_escape','hybrid_rule_v4_fast_progress_static_escape_continuous']
PROBES={'planner_sanity_simple','classic_head_on_corridor_low','classic_crossing_low','classic_doorway_low','classic_overtaking_low','francis2023_following_human'}
p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('out',type=Path);a=p.parse_args()
rows={};members={};heads=set();summaries={};runtime_rows=[];drivers=set()
for mode in ['off','contact','wall','on']:
 for suite,n in [('main',48),('width',3),('probes',6)]:
  for arm in ARMS:
   for seed in range(1001,1011):
    d=a.root/mode/suite/arm/str(seed)
