"""Retain the exact recurrence failure report before pytest removes its fixture."""
import hashlib,os,shutil
from pathlib import Path
import pytest

@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
 outcome=yield
 report=outcome.get_result()
 if report.failed and 'test_real_registry_recurrence_passes' in item.nodeid:
  temporary=item.funcargs.get('tmp_path')
  if temporary is not None:
   source=Path(temporary)/'report.json'
   if source.exists():
    root=Path(os.environ['PEDCONTACT_FAILURE_ROOT']);root.mkdir(parents=True,exist_ok=True)
    target=root/(hashlib.sha256(item.nodeid.encode()).hexdigest()[:12]+'.json')
    shutil.copyfile(source,target)

